// EmailData holds the values rendered into the email layout.
type EmailData struct {
	SiteName   string
	SiteURL    string
	Name       string // optional; "سلام،" is used when empty
	Title      string
	Message    string
	Preheader  string
	Code       string // optional; shown in a highlighted code box
	ButtonText string // optional; button is hidden when ButtonURL is empty
	ButtonURL  string
	Year       int
}

